/** Paths changed since the last commit outside `.sofar` (a --no-score session must change none). */
export async function codeChangedOutsideStore(paths: CellPaths): Promise<string[]> {
  const out = await git(paths.repo, "status", "--porcelain", "--untracked-files=all", "--", ".", ":(exclude).sofar")
  return out.split("\\n").filter(Boolean).map((l) => l.slice(3))
