/**
 * Per-task scores for a whole-run cell (drive, orchestrator), bench-refresh D33. A task's commit is the
 * newest whose subject starts with "<id>:". Failing that, when drive recorded the task's task_done time,
 * it is the newest non-bench commit at or before that time. Each commit is checked out in a scratch
 * worktree and scored with the suites up to that task; a task with no commit stays unscored.
 */
export async function scoreTaskCommits(
  paths: CellPaths,
  sessionIds: string[],
  taskDoneAt: Record<string, string>,
  outDir: string,
  wrap: <T>(fn: () => Promise<T>) => Promise<T>,
): Promise<Record<string, TaskScore>> {
  const log = (await git(paths.repo, "log", "--format=%H%x09%ct%x09%s", "HEAD"))
    .split("\\n")
    .filter(Boolean)
    .map((l) => {
      const [sha, ct, ...subject] = l.split("\\t")
      return { sha: sha as string, ms: Number(ct) * 1000, subject: subject.join("\\t") }
    })
  const result: Record<string, TaskScore> = {}
  for (let i = 0; i < sessionIds.length; i++) {
    const sid = sessionIds[i] as string
    let hit = log.find((c) => c.subject.startsWith(`${sid}:`))
    let matchedBy: TaskScore["matchedBy"] = hit ? "subject" : "none"
    const doneMs = Date.parse(taskDoneAt[sid] ?? "")
    if (!hit && Number.isFinite(doneMs)) {
      // Commit times have second resolution; allow the second the handoff was written in.
      hit = log.find((c) => !c.subject.startsWith("bench:") && c.ms <= doneMs + 999)
      if (hit) matchedBy = "handoff-time"
    }
    if (!hit) {
      result[sid] = { commit: null, matchedBy }
      continue
    }
    const tree = join(paths.dir, "task-worktrees", sid)
    const taskOut = join(outDir, `task-${sid}`)
    mkdirSync(taskOut, { recursive: true })
    rmSync(tree, { recursive: true, force: true })
    await git(paths.repo, "worktree", "add", "-q", "--detach", tree, hit.sha)
    try {
      const scored = await wrap(() => score({ ...paths, repo: tree }, sessionIds.slice(0, i + 1), taskOut))
      result[sid] = { commit: hit.sha, matchedBy, ...scored }
    } finally {
      await git(paths.repo, "worktree", "remove", "--force", tree)
    }
  }
  return result
}

/** The commit whose subject is exactly `bench: after <sid>` (a sessions-mode checkpoint), or null. */
export async function checkpointCommit(repo: string, sid: string): Promise<string | null> {
  const log = await git(repo, "log", "--format=%H%x09%s", "HEAD")
  for (const line of log.split("\\n")) {
    const [sha, subject] = line.split("\\t")
    if (subject === `bench: after ${sid}`) return sha ?? null
  }
  return null
}

/**
 * Start a cell from a parent cell's checkpoint (bench-refresh D33). The repo, record included, is cloned
 * at the parent's `bench: after <sid>` commit. A memory store the parent kept outside the repo is restored
 * from the parent's snapshot for that session when the child is the same agent; a different agent could
 * not read it, which is what a cross-agent hand-off (C6) measures, so it is noted rather than copied.
 */
export async function forkCell(parent: { paths: CellPaths; arm: Arm }, at: string, child: { paths: CellPaths; arm: Arm }): Promise<{ commit: string; memory: string }> {
  const commit = await checkpointCommit(parent.paths.repo, at)
  if (!commit) throw new Error(`no "bench: after ${at}" commit in ${parent.paths.repo}`)
  if (existsSync(child.paths.repo)) throw new Error(`${child.paths.repo} already exists`)
  mkdirSync(child.paths.artifacts, { recursive: true })
  const r = await run(["git", "clone", "--no-hardlinks", "-q", parent.paths.repo, child.paths.repo], { cwd: child.paths.dir, env: scrubbedEnv(), timeoutMs: 300_000 })
  if (r.code !== 0) throw new Error(`clone failed: ${r.stderr}`)
  await git(child.paths.repo, "checkout", "-q", "-B", "main", commit)
  await git(child.paths.repo, "remote", "remove", "origin")
  await git(child.paths.repo, "clean", "-qfdx")

  const snap = join(parent.paths.artifacts, at)
  let memory = "none outside the repo"
  const sameAgent = parent.arm.agent === child.arm.agent
  const external: Array<[string, string]> = []
  if (parent.arm.id === "claude-automemory") {
    external.push([join(snap, "memory"), join(CLAUDE_CONFIG, "projects", child.paths.repo.replace(/[^a-zA-Z0-9]/g, "-"), "memory")])
  }
  if (parent.arm.id === "claude-obsidian") external.push([join(snap, "vault"), join(child.paths.dir, "vault")])
  if (parent.arm.agent === "codex") external.push([join(snap, "codex-memories"), join(child.paths.dir, "codex-home", "memories")])
  for (const [src, dest] of external) {
    if (!existsSync(src)) {
      memory = `parent snapshot ${src} missing`
      continue
    }
    if (!sameAgent) {
      memory = `not carried: ${parent.arm.agent}'s store at ${src} is not readable by ${child.arm.agent}`
      continue
    }
    mkdirSync(dest, { recursive: true })
    cpSync(src, dest, { recursive: true })
    memory = `restored ${src} → ${dest}`
  }

  await child.arm.setup({ repo: child.paths.repo, cellDir: child.paths.dir })
  await git(child.paths.repo, "add", "-A")
  await git(child.paths.repo, "commit", "-q", "--allow-empty", "-m", `bench: ${child.arm.id} setup, fork of ${parent.arm.id} after ${at}`)
  return { commit, memory }
}
